const input = $json.body ?? $json;
const count = Math.min(Math.max(Number(input.count || 5), 1), 30);
const category = input.category_name || 'ثقافة عامة';
const difficulty = input.difficulty || 'medium';
const language = input.language || 'ar';

return [{
  json: {
    category_id: input.category_id || null,
    category_name: category,
    count,
    difficulty,
    language,
    callback_url: input.callback_url,
    callback_api_key: input.callback_api_key,
    prompt: `Generate exactly ${count} unique trivia questions in ${language} about ${category}. Difficulty: ${difficulty}. Return ONLY valid JSON with this shape: {\"questions\":[{\"question_text\":\"...\",\"options_json\":[\"...\",\"...\",\"...\",\"...\"],\"correct_answer\":\"...\",\"points_level\":200,\"category_name\":\"${category}\"}]}. Every question must have exactly four distinct options, and correct_answer must exactly match one option. Use points_level values 200, 400, or 600.`
  }
}];

const request = $('Prepare AI prompt').first().json;
const content = $json.choices?.[0]?.message?.content;
if (!content) throw new Error('OpenAI returned no message content');
const parsed = typeof content === 'string' ? JSON.parse(content) : content;
if (!Array.isArray(parsed.questions) || parsed.questions.length === 0) throw new Error('AI response contains no questions');

return [{
  json: {
    callback_url: request.callback_url,
    callback_api_key: request.callback_api_key,
    category_id: request.category_id,
    category_name: request.category_name,
    questions: parsed.questions.map((question) => ({
      ...question,
      category_id: question.category_id || request.category_id,
      category_name: question.category_name || request.category_name,
      options_json: Array.isArray(question.options_json) ? question.options_json : [],
      points_level: Number(question.points_level || 200)
    }))
  }
}];
